create extension if not exists pgcrypto;
create type public.order_status as enum ('NEW','ACCEPTED','PREPARING','READY','COMPLETED','CANCELLED');
create type public.option_type as enum ('variant','addon');
create table public.cafe_settings(id uuid primary key default gen_random_uuid(), cafe_name text not null default 'Your Café', tagline text, logo_url text, accent_color text not null default '#a34d2d', timezone text not null default 'Asia/Kolkata', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.admin_profiles(user_id uuid primary key references auth.users(id) on delete cascade, role text not null check(role in('owner','admin')), created_at timestamptz not null default now());
create table public.menu_categories(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,sort_order int not null default 0,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.menu_items(id uuid primary key default gen_random_uuid(),category_id uuid not null references public.menu_categories(id) on delete restrict,name text not null,description text,price_paise int not null check(price_paise>=0),image_url text,is_veg boolean not null default true,is_available boolean not null default true,sort_order int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.menu_item_options(id uuid primary key default gen_random_uuid(),menu_item_id uuid not null references public.menu_items(id) on delete cascade,name text not null,option_type public.option_type not null,group_name text not null default 'Default',price_delta_paise int not null default 0 check(price_delta_paise>=0),is_required boolean not null default false,min_selections int not null default 0 check(min_selections>=0),max_selections int not null default 1 check(max_selections>0),is_available boolean not null default true,sort_order int not null default 0,check(min_selections<=max_selections));
create table public.cafe_tables(id uuid primary key default gen_random_uuid(),table_number int not null unique check(table_number>0),label text not null,qr_token uuid not null unique default gen_random_uuid(),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create sequence public.order_number_seq;
create table public.orders(id uuid primary key default gen_random_uuid(),order_number bigint not null unique default nextval('public.order_number_seq'),table_id uuid not null references public.cafe_tables(id) on delete restrict,status public.order_status not null default 'NEW',customer_name text,customer_note text,subtotal_paise int not null check(subtotal_paise>=0),total_paise int not null check(total_paise>=0),idempotency_key uuid not null unique,created_at timestamptz not null default now(),accepted_at timestamptz,completed_at timestamptz,cancelled_at timestamptz,cancellation_reason text);
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,menu_item_id uuid references public.menu_items(id) on delete set null,item_name_snapshot text not null,unit_price_paise int not null check(unit_price_paise>=0),quantity int not null check(quantity between 1 and 20),selected_options_snapshot jsonb not null default '[]',line_total_paise int not null check(line_total_paise>=0),item_note text);
create index orders_table_created_idx on public.orders(table_id,created_at desc); create index orders_status_created_idx on public.orders(status,created_at desc); create index menu_items_category_idx on public.menu_items(category_id,sort_order);
alter table public.cafe_settings enable row level security; alter table public.admin_profiles enable row level security; alter table public.menu_categories enable row level security; alter table public.menu_items enable row level security; alter table public.menu_item_options enable row level security; alter table public.cafe_tables enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security;
create function public.is_admin() returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from public.admin_profiles where user_id=auth.uid())$$;
create policy "public reads active categories" on public.menu_categories for select using(is_active); create policy "public reads visible items" on public.menu_items for select using(exists(select 1 from public.menu_categories c where c.id=category_id and c.is_active)); create policy "public reads available options" on public.menu_item_options for select using(exists(select 1 from public.menu_items i join public.menu_categories c on c.id=i.category_id where i.id=menu_item_id and c.is_active)); create policy "public reads active tables by token" on public.cafe_tables for select using(is_active);
create policy "admins manage settings" on public.cafe_settings for all using(public.is_admin()) with check(public.is_admin()); create policy "admins manage categories" on public.menu_categories for all using(public.is_admin()) with check(public.is_admin()); create policy "admins manage items" on public.menu_items for all using(public.is_admin()) with check(public.is_admin()); create policy "admins manage options" on public.menu_item_options for all using(public.is_admin()) with check(public.is_admin()); create policy "admins manage tables" on public.cafe_tables for all using(public.is_admin()) with check(public.is_admin()); create policy "admins read profiles" on public.admin_profiles for select using(public.is_admin()); create policy "admins read orders" on public.orders for select using(public.is_admin()); create policy "admins update orders" on public.orders for update using(public.is_admin()) with check(public.is_admin()); create policy "admins read order items" on public.order_items for select using(public.is_admin());
create function public.place_public_order(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_table public.cafe_tables; v_order public.orders; v_item jsonb; v_menu public.menu_items; v_qty int; v_options jsonb; v_option_total int; v_total int:=0; v_line int;
begin
 if jsonb_array_length(coalesce(p_payload->'items','[]'::jsonb)) not between 1 and 25 then raise exception 'invalid item count'; end if;
 select * into v_table from cafe_tables where qr_token=(p_payload->>'tableToken')::uuid and is_active; if not found then raise exception 'invalid table'; end if;
 select * into v_order from orders where idempotency_key=(p_payload->>'idempotencyKey')::uuid; if found then return jsonb_build_object('order_number',v_order.order_number,'table_label',v_table.label,'status',v_order.status,'total_paise',v_order.total_paise); end if;
 for v_item in select * from jsonb_array_elements(p_payload->'items') loop v_qty=(v_item->>'quantity')::int; if v_qty not between 1 and 20 then raise exception 'invalid quantity'; end if; select * into v_menu from menu_items where id=(v_item->>'menuItemId')::uuid and is_available; if not found then raise exception 'unavailable item'; end if; select coalesce(jsonb_agg(jsonb_build_object('name',o.name,'price_delta_paise',o.price_delta_paise)),'[]'::jsonb),coalesce(sum(o.price_delta_paise),0) into v_options,v_option_total from menu_item_options o where o.id in(select value::uuid from jsonb_array_elements_text(coalesce(v_item->'optionIds','[]'::jsonb))) and o.menu_item_id=v_menu.id and o.is_available; if jsonb_array_length(v_options)<>jsonb_array_length(coalesce(v_item->'optionIds','[]'::jsonb)) then raise exception 'invalid option'; end if; v_line=(v_menu.price_paise+v_option_total)*v_qty; v_total=v_total+v_line; end loop;
 insert into orders(table_id,customer_name,customer_note,subtotal_paise,total_paise,idempotency_key) values(v_table.id,nullif(left(p_payload->>'customerName',60),''),nullif(left(p_payload->>'customerNote',300),''),v_total,v_total,(p_payload->>'idempotencyKey')::uuid) returning * into v_order;
 for v_item in select * from jsonb_array_elements(p_payload->'items') loop select * into v_menu from menu_items where id=(v_item->>'menuItemId')::uuid; v_qty=(v_item->>'quantity')::int; select coalesce(jsonb_agg(jsonb_build_object('name',o.name,'price_delta_paise',o.price_delta_paise)),'[]'::jsonb),coalesce(sum(o.price_delta_paise),0) into v_options,v_option_total from menu_item_options o where o.id in(select value::uuid from jsonb_array_elements_text(coalesce(v_item->'optionIds','[]'::jsonb))); insert into order_items(order_id,menu_item_id,item_name_snapshot,unit_price_paise,quantity,selected_options_snapshot,line_total_paise,item_note) values(v_order.id,v_menu.id,v_menu.name,v_menu.price_paise,v_qty,v_options,(v_menu.price_paise+v_option_total)*v_qty,nullif(left(v_item->>'note',180),'')); end loop;
 return jsonb_build_object('order_number',v_order.order_number,'table_label',v_table.label,'status',v_order.status,'total_paise',v_order.total_paise);
end $$;
revoke all on function public.place_public_order(jsonb) from public; grant execute on function public.place_public_order(jsonb) to service_role;
